def execute(arguments):
    """
    条件检查

    参数:
        arguments (dict): 包含以下字段
            - value (any): 要检查的值，必填
            - operator (str): 比较操作符，必填
                - "==": 等于
                - "!=": 不等于
                - ">": 大于
                - ">=": 大于等于
                - "<": 小于
                - "<=": 小于等于
                - "contains": 包含（字符串/列表）
                - "not_contains": 不包含
                - "starts_with": 以...开头
                - "ends_with": 以...结尾
                - "is_empty": 为空
                - "is_not_empty": 不为空
                - "is_type": 类型检查
                - "in": 在列表中
                - "not_in": 不在列表中
                - "matches": 正则匹配
            - expected (any): 期望值，部分操作符必填
            - case_sensitive (bool): 是否区分大小写，默认 True

    返回:
        dict: 包含检查结果的字典
            - success (bool): 是否成功
            - result (bool): 条件是否满足
            - value (any): 实际值
            - expected (any): 期望值
            - operator (str): 使用的操作符
            - error (str): 错误信息（失败时）
    """
    import re

    value = arguments.get("value")
    operator = arguments.get("operator", "")
    expected = arguments.get("expected")
    case_sensitive = arguments.get("case_sensitive", True)

    if not operator:
        return {"success": False, "error": "请提供比较操作符"}

    try:
        def compare(v, e):
            if not case_sensitive:
                if isinstance(v, str):
                    v = v.lower()
                if isinstance(e, str):
                    e = e.lower()
            return v, e

        result = False

        if operator == "==":
            result = value == expected
        elif operator == "!=":
            result = value != expected
        elif operator == ">":
            result = value > expected
        elif operator == ">=":
            result = value >= expected
        elif operator == "<":
            result = value < expected
        elif operator == "<=":
            result = value <= expected
        elif operator == "contains":
            v, e = compare(str(value), str(expected))
            result = e in v
        elif operator == "not_contains":
            v, e = compare(str(value), str(expected))
            result = e not in v
        elif operator == "starts_with":
            v, e = compare(str(value), str(expected))
            result = v.startswith(e)
        elif operator == "ends_with":
            v, e = compare(str(value), str(expected))
            result = v.endswith(e)
        elif operator == "is_empty":
            if value is None:
                result = True
            elif isinstance(value, (str, list, dict)):
                result = len(value) == 0
            else:
                result = False
        elif operator == "is_not_empty":
            if value is None:
                result = False
            elif isinstance(value, (str, list, dict)):
                result = len(value) > 0
            else:
                result = True
        elif operator == "is_type":
            type_map = {
                "string": str, "int": int, "float": float,
                "bool": bool, "list": list, "dict": dict,
                "none": type(None)
            }
            expected_type = type_map.get(expected, type(None))
            result = isinstance(value, expected_type)
        elif operator == "in":
            if isinstance(expected, (list, tuple)):
                result = value in expected
            else:
                return {"success": False, "error": "'in'操作符期望expected为列表"}
        elif operator == "not_in":
            if isinstance(expected, (list, tuple)):
                result = value not in expected
            else:
                return {"success": False, "error": "'not_in'操作符期望expected为列表"}
        elif operator == "matches":
            pattern = re.compile(expected, 0 if case_sensitive else re.IGNORECASE)
            result = bool(pattern.search(str(value)))
        else:
            return {"success": False, "error": f"未知的操作符: {operator}"}

        return {
            "success": True,
            "result": result,
            "value": value,
            "expected": expected,
            "operator": operator
        }
    except Exception as e:
        return {"success": False, "error": f"检查失败: {str(e)}"}
